'use strict';
/* Mini Crossword: every puzzle in js/data/crosswords.js (generated by tools/gen-crossword.js)
   is a proper crossword - clue keys match its words, no short words, connected, the right
   size for its level, dense or open as it says, clean clues - and the set covers every pack
   and level. The checks live in tools/crossword/validate.js so the generator refuses to
   write a bad file too. */
const { loadFF, test, assert, assertEqual } = require('./harness');
const V = require('../crossword/validate');

let cached = null;
const app = () => cached || (cached = loadFF(['js/core.js', 'js/crossword/rules.js', 'js/data/crosswords.js']));
const list = () => app().data.crosswords;
let rulesOnly = null;
const rules = () => (rulesOnly || (rulesOnly = loadFF(['js/core.js', 'js/crossword/rules.js']))).CrosswordRules;

test('crossword data: the file loads with puzzles', function () {
  assert(Array.isArray(list()) && list().length > 0, 'FF.data.crosswords is a non-empty list');
});

test('crossword data: every puzzle passes the validator', function () {
  const R = app().CrosswordRules;
  const problems = [];
  list().forEach((p) => V.validatePuzzle(p, R).forEach((m) => problems.push(p.id + ': ' + m)));
  assertEqual(problems.slice(0, 20), []);
});

test('crossword data: ids are unique', function () {
  const seen = {};
  const dups = list().filter((p) => (seen[p.id] = (seen[p.id] || 0) + 1) > 1).map((p) => p.id);
  assertEqual(dups, []);
});

test('crossword data: coverage of packs and levels', function () {
  const R = app().CrosswordRules;
  assertEqual(V.coverage(list(), R), []);
});

/* The validator itself catches what it should (so a green data test means something). */
const GOOD = {
  id: 'an-e-001', level: 'easy', pack: 'animals', size: 5, kind: 'open',
  rows: ['CAMEL', 'O#A#I', 'WHALE', 'L#Z#N', 'STARE'],
  clues: { '1A': 'Desert animal with a hump', '1D': 'Hooded robes worn by monks', '2D': 'A puzzle with paths', '3D': 'King of the jungle', '4A': 'Largest animal in the sea', '5A': 'Look at for a long time' }
};

test('crossword validator: a good puzzle has no problems', function () {
  assertEqual(V.validatePuzzle(GOOD, rules()), []);
});

test('crossword validator: catches missing clues, answers in clues, short words and bad sizes', function () {
  const R = rules();
  const has = (p, re) => V.validatePuzzle(p, R).some((m) => re.test(m));
  const c1 = JSON.parse(JSON.stringify(GOOD)); delete c1.clues['4A'];
  assert(has(c1, /clue keys/), 'missing clue');
  const c2 = JSON.parse(JSON.stringify(GOOD)); c2.clues['4A'] = 'A whale of a time';
  assert(has(c2, /answer in clue/), 'answer in clue');
  const c3 = JSON.parse(JSON.stringify(GOOD)); c3.clues['4A'] = 'largest animal';
  assert(has(c3, /capital/), 'lower-case start');
  const c4 = JSON.parse(JSON.stringify(GOOD)); c4.level = 'hard';
  assert(has(c4, /size/), 'size for level');
  const c5 = JSON.parse(JSON.stringify(GOOD)); c5.rows = ['CA#EL', 'O#A#I', 'WHALE', 'L#Z#N', 'ST#RE'];
  assert(has(c5, /short|symmetric|clue keys/), 'two-letter words');
  const c6 = JSON.parse(JSON.stringify(GOOD)); c6.kind = 'dense';
  assert(has(c6, /checked/), 'dense must be fully checked');
  const c7 = JSON.parse(JSON.stringify(GOOD)); c7.clues['5A'] = c7.clues['4A'];
  assert(has(c7, /same clue/), 'duplicate clue');
});

test('crossword bank lint: format, levels, answer in clue, easy length', function () {
  const ok = 'CAMEL|enh|A desert animal with a hump|Ship of the desert|It can go for days without a drink, famously';
  assertEqual(V.lintBank(ok, 'animals'), []);
  const has = (t, re) => V.lintBank(t, 'animals').some((m) => re.test(m));
  assert(has('CAMEL|enh|A camel|x|y', /answer in clue|capital/), 'answer in clue');
  assert(has('CAMEL|en|Desert animal||', /missing normal/), 'missing clue');
  assert(has('ELEPHANT|e|Big grey animal||', /5 letters/), 'easy too long');
  assert(has('Camel|n||Desert animal|', /capital letters/), 'lower-case word');
  assert(has(ok + '\n' + ok, /twice/), 'duplicate');
  assert(has('CAMEL|enh|Desert animal', /5 fields/), 'field count');
  assertEqual(V.lintBank('# note\nZZZ\n', 'blocked'), []);
});

test('crossword generator: a fill never uses the same answer twice', function () {
  const G = require('../gen-crossword');
  // A grid the generator once made: placing 9A SPY also completed 7D as SPY. With only these
  // words the grid has no fill without that repeat, so the answer is no fill at all.
  const idx = G.makeIndex(['BUS', 'BUY', 'USES', 'SEATS', 'USED', 'DROP', 'YEARS', 'SPY', 'STOP']);
  const rows = G.fill(['...##', '....#', '.....', '#....', '##...'], idx, G.rngFrom('t'), () => 0, 4000, null);
  assertEqual(rows, null);
});
